examples.template:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space3) {
    Text({{paragraph}})
    MonarchButton({{button}}, variant: .secondary, size: .sm) {}
    MonarchAiInlinePrompt(
        context: {{paragraph}},
        suggestions: [{{suggestions.0}}, {{suggestions.1}}, {{suggestions.2}}]
    ) { _ in }
    .monarchAiPopoverCard()
}

examples.code:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space3) {
    Text("The team shipped the new onboarding flow in March. Early numbers suggest more people finish setup on their first visit, although the sample is still small and support tickets have not changed much yet.")
    MonarchButton("Edit paragraph with AI", variant: .secondary, size: .sm) {}
    MonarchAiInlinePrompt(
        context: "The team shipped the new onboarding flow in March. Early numbers suggest more people finish setup on their first visit, although the sample is still small and support tickets have not changed much yet.",
        suggestions: ["Shorten", "Make it more formal", "Fix spelling and grammar"]
    ) { _ in }
    .monarchAiPopoverCard()
}

VStack(alignment: .leading) {
    MonarchAiInlinePromptArea(onAskAi: { isAsking = true }, content: {
        Text(paragraph).monarchTextStyle(.body)
    })
    MonarchButton("Edit paragraph with AI", systemImage: "text.bubble", size: .sm) {
        isAsking = true
    }
}
.sheet(isPresented: $isAsking) {
    MonarchAiInlinePrompt(context: paragraph, closesOnSubmit: false) { _ in }
}

MonarchAiInlinePrompt(
    context: "Early numbers suggest more people finish setup on their first visit.",
    suggestions: ["Shorten"],
    initialValue: "Make it friendlier",
    isPending: true
) { _ in }
